#include "al_group_solver.h"
#include <future>
namespace al {
std::vector<std::vector<size_t>> groupBuilders(const std::vector<Builder>& a){std::vector<std::vector<size_t>> groups;std::vector<uint8_t> seen(a.size());for(size_t i=0;i<a.size();i++)if(!seen[i]){std::vector<size_t> g{i};seen[i]=1;for(size_t head=0;head<g.size();head++)for(size_t j=0;j<a.size();j++)if(!seen[j]){bool linked=false;for(auto b:a[g[head]].boundary)linked|=b.levelBuilderUid==a[j].uid;for(auto b:a[j].boundary)linked|=b.levelBuilderUid==a[g[head]].uid;if(linked){seen[j]=1;g.push_back(j);}}groups.push_back(g);}return groups;}
void connectBuilders(Builder& a,Builder& b,int d,bool connect){if(a.repoUid!=b.repoUid)throw std::runtime_error("boundary builder uses a different repo");int axis=d%3==0?0:d%3==1?2:1;if(connect){a.boundary[d].levelBuilderUid=b.uid;b.boundary[opposite(d)].levelBuilderUid=a.uid;auto pos=b.levelData.position;pos[axis]=d>=3?a.levelData.position[axis]+a.levelData.size[axis]:a.levelData.position[axis]-b.levelData.size[axis];resize(b,pos,b.levelData.size,int(std::max(size_t(1),b.levelData.layers.size())));}else{a.boundary[d].levelBuilderUid.clear();if(b.boundary[opposite(d)].levelBuilderUid==a.uid)b.boundary[opposite(d)].levelBuilderUid.clear();auto p=b.levelData.position;p[axis]+=(d>=3?1:-1)*b.levelData.size[axis];resize(b,p,b.levelData.size,int(std::max(size_t(1),b.levelData.layers.size())));}}
SolveRequest builderRequest(const RepoRuntime& r,Builder& b,const std::vector<Builder>& all,const EditorSettings& settings,bool selection,std::atomic<bool>* cancel,std::atomic<float>* progress){SolveRequest q;q.repo=&r;q.level=&b.levelData;q.inputWave=&b.inputWave;q.layer=b.currentLayer;q.bounds=selection?Bounds3i{b.selection.min-b.levelData.position,b.selection.max-b.levelData.position}:Bounds3i{{},b.levelData.size};q.iterations=settings.maxIterations;q.seed=uint32_t(b.seed);q.cellPick=b.cellPick;q.moduleWeightMultipliers=b.moduleWeightMultipliers;q.cancel=cancel;q.progress=progress;q.multiThreaded=b.useMultiThreadedSolver;q.keepLargestComponent=!selection&&b.keepLargestComponent;q.minCoverage=selection?0:b.minCoverage;q.requireAllFloors=!selection&&b.requireAllFloors;for(auto& name:r.weightGroups){auto i=std::find_if(b.groupsWeights.begin(),b.groupsWeights.end(),[&](auto g){return g.weightGroup==name;});q.weightOverride.push_back(i!=b.groupsWeights.end()&&i->overrideWeight?i->weight:-1);}
 for(int d=0;d<6;d++){uint32_t mask=0;for(auto name:b.boundary[d].groups){auto it=std::find(r.groups.begin(),r.groups.end(),name);if(it!=r.groups.end())mask|=1u<<std::distance(r.groups.begin(),it);}auto id=b.boundary[d].levelBuilderUid;if(!id.empty()){auto other=std::find_if(all.begin(),all.end(),[&](auto& x){return x.uid==id;});if(other==all.end())throw std::runtime_error("boundary builder was deleted");if(other->repoUid!=b.repoUid)throw std::runtime_error("boundary builder uses a different repo");q.boundaries[d]=std::make_shared<LevelBoundary>(&*other,mask);}else if(mask)q.boundaries[d]=std::make_shared<GroupsBoundary>(mask);}return q;}
GroupResult solveBuilders(std::vector<Builder>& all,const std::map<std::string,std::shared_ptr<const RepoRuntime>>& repos,const std::vector<size_t>& indices,const EditorSettings& settings,std::atomic<bool>* cancel,std::atomic<float>* progress){GroupResult result;auto original=all;auto started=std::chrono::steady_clock::now();for(int iteration=0;iteration<settings.maxIterations;iteration++){if(cancel&&cancel->load()){result.message="cancelled";return result;}if(std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count()>15){result.message="group build time budget exceeded";return result;}auto work=original;bool ok=true;std::set<size_t> remaining(indices.begin(),indices.end());result.results.clear();result.order.clear();while(!remaining.empty()&&ok){
 std::vector<size_t> ready;bool parallel=false;for(auto i:remaining){bool dependent=false;for(auto side:work[i].boundary)for(auto j:remaining)if(i!=j&&side.levelBuilderUid==work[j].uid)dependent=true;if(!dependent){ready.push_back(i);parallel|=work[i].useMultiThreadedSolver;}}
 if(ready.size()>8)ready.resize(8);
 if(parallel&&ready.size()>1){
  using Built=std::pair<Builder,std::vector<SolveResult>>;std::vector<std::future<Built>> jobs;
  for(auto i:ready)jobs.push_back(std::async(std::launch::async,[&,i](){Builder b=work[i];auto& r=*repos.at(b.repoUid);auto q=builderRequest(r,b,work,settings,false,cancel,progress);q.iterations=1;q.multiThreaded=false;q.seed=uint32_t(hash64(b.seed?b.seed:1,iteration));int last=b.rebuildBottomLayers&&b.autoAdvanceLayers?int(r.layerRange.size())-1:b.currentLayer,first=b.rebuildBottomLayers?0:b.currentLayer;std::vector<SolveResult> results;for(int l=first;l<=last;l++){q.layer=l;auto solved=solve(q);if(!solved.iterationsUsed)throw std::runtime_error("parallel builder failed");results.push_back(solved);}return Built{std::move(b),std::move(results)};}));
  std::vector<Built> built;for(auto& job:jobs)try{built.push_back(job.get());}catch(...){ok=false;built.push_back({});}if(!ok)break;
  for(size_t n=0;n<ready.size();n++){work[ready[n]]=std::move(built[n].first);result.results.insert(result.results.end(),built[n].second.begin(),built[n].second.end());result.order.push_back(ready[n]);remaining.erase(ready[n]);}continue;
 }
 size_t chosen=*remaining.begin();size_t best=SIZE_MAX;for(auto i:remaining){size_t deps=0;for(auto side:work[i].boundary)for(auto j:remaining)if(side.levelBuilderUid==work[j].uid&&i!=j)deps++;if(deps<best){best=deps;chosen=i;}}auto& b=work[chosen];auto repo=repos.find(b.repoUid);if(repo==repos.end())throw std::runtime_error("The Repo isn't assigned!");auto& r=*repo->second;auto q=builderRequest(r,b,work,settings,false,cancel,progress);q.iterations=1;q.seed=uint32_t(hash64(b.seed?b.seed:1,iteration));int last=b.rebuildBottomLayers&&b.autoAdvanceLayers?int(r.layerRange.size())-1:b.currentLayer,first=b.rebuildBottomLayers?0:b.currentLayer;for(int l=first;l<=last;l++){q.layer=l;auto solved=solve(q);result.results.push_back(solved);if(!solved.iterationsUsed){ok=false;break;}}remaining.erase(chosen);result.order.push_back(chosen);}
 if(ok){for(auto i:indices){auto& b=work[i];auto& r=*repos.at(b.repoUid);for(int d=0;d<6;d++)if(!b.boundary[d].levelBuilderUid.empty()){auto other=std::find_if(work.begin(),work.end(),[&](auto& x){return x.uid==b.boundary[d].levelBuilderUid;});if(other==work.end())continue;for(size_t c=0;c<volume(b.levelData.size);c++){auto p=position(c,b.levelData.size);if(inside(p+delta[d],b.levelData.size))continue;auto np=p+b.levelData.position+delta[d]-other->levelData.position;if(!inside(np,other->levelData.size))continue;for(size_t l=0;l<std::min(b.levelData.layers.size(),other->levelData.layers.size());l++){auto a=b.levelData.layers[l].blocks[c],z=other->levelData.layers[l].blocks[index(np,other->levelData.size)];if(a&&z&&!r.compatible(r.byHash(a),d,r.byHash(z)))ok=false;}}}}}
 if(ok){all=std::move(work);result.success=true;result.message="build succeeded";return result;}}
 result.message="build failed! Group transaction was not applied.";return result;}
}
